<?php
/**
 * Ready-made sections as block patterns, translated (feature pbs-c1).
 *
 * @package ZinnDigital\PBS
 */

declare( strict_types = 1 );

namespace ZinnDigital\PBS\Cloud;

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Registers the section patterns shipped with the plugin (`includes/cloud/patterns/*.php`; the
 * premium package adds its own from the Pro directory).
 *
 * ⭐ The pattern files are GENERATED by the kit builder (src/kits/__tests__/kits.test.js) from the
 * same sources as the website kits, so their markup is what each block's own save() writes. Every
 * visible string in them is a `__()` call, so a pattern ships in all the plugin's languages like
 * any other string (§2.19); {@see self::fill()} puts the translations back into the markup in the
 * two escapings a block needs — JSON inside the block comment, HTML in the saved markup.
 */
final class Patterns {

	/** The pattern category. */
	public const CATEGORY = 'pbs-sections';

	/**
	 * Hook registration.
	 *
	 * @return void
	 */
	public static function register(): void {
		add_action( 'init', array( self::class, 'load' ) );
	}

	/**
	 * Register the category and every pattern file in a directory.
	 *
	 * @param string $dir Directory of generated pattern files ('' = the free set).
	 * @return void
	 */
	public static function load( string $dir = '' ): void {
		if ( ! function_exists( 'register_block_pattern' ) ) {
			return;
		}
		if ( ! \WP_Block_Pattern_Categories_Registry::get_instance()->is_registered( self::CATEGORY ) ) {
			register_block_pattern_category(
				self::CATEGORY,
				array(
					'label'       => __( 'Page Builder Sandwich sections', 'page-builder-sandwich' ),
					'description' => __( 'Ready-made sections from Page Builder Sandwich.', 'page-builder-sandwich' ),
				)
			);
		}
		$dir   = '' === $dir ? __DIR__ . '/patterns' : $dir;
		$files = glob( trailingslashit( $dir ) . '*.php' );
		foreach ( is_array( $files ) ? $files : array() as $file ) {
			$pattern = include $file;
			if ( ! is_array( $pattern ) || empty( $pattern['content'] ) ) {
				continue;
			}
			register_block_pattern(
				'pbs/' . basename( $file, '.php' ),
				array(
					'title'      => (string) $pattern['title'],
					'categories' => array( self::CATEGORY ),
					'keywords'   => (array) ( $pattern['keywords'] ?? array() ),
					'content'    => (string) $pattern['content'],
				)
			);
		}
	}

	/**
	 * Put the translated strings into a pattern's markup.
	 *
	 * Tokens are `@@PBS_T<n>@@`. Inside a block comment (`<!-- wp:name {json} -->`) the string is
	 * written the way core serialises block attributes (serialize_block_attributes: JSON with
	 * `--`, `<`, `>`, `&` and `"` escaped as \u sequences); everywhere else it is HTML-escaped,
	 * except that the few strings authored with inline markup keep it (wp_kses_post).
	 *
	 * @param string             $markup  Markup with tokens.
	 * @param array<int, string> $strings Translated strings, by token number.
	 * @return string
	 */
	public static function fill( string $markup, array $strings ): string {
		$json  = static function ( string $s ): string {
			return substr( serialize_block_attributes( array( $s ) ), 2, -2 );
		};
		$html  = static function ( string $s ): string {
			// Only a string that really holds a tag keeps markup ("<5 min" is text, not a tag).
			return preg_match( '#</?[a-z][a-z0-9]*[\s/>]#i', $s ) ? wp_kses_post( $s ) : esc_html( $s );
		};
		$token = '/@@PBS_T(\d+)@@/';

		// Block comments first (their JSON), then what is left is HTML.
		$markup = (string) preg_replace_callback(
			'/<!-- \/?wp:[a-z0-9\/-]+ \{.*?\} \/?-->/s',
			static function ( array $m ) use ( $json, $strings, $token ): string {
				return (string) preg_replace_callback(
					$token,
					static fn( array $t ): string => $json( (string) ( $strings[ (int) $t[1] ] ?? '' ) ),
					$m[0]
				);
			},
			$markup
		);

		return (string) preg_replace_callback(
			$token,
			static fn( array $t ): string => $html( (string) ( $strings[ (int) $t[1] ] ?? '' ) ),
			$markup
		);
	}
}
